{"l":6334,"g":7,"b":3,"cefr":"B1","role":"challenge","insight":"reframing","k":"h","q":"Hvad betyder 'Take care!', når man siger farvel?","o":["Tag den!","Vær forsigtig med den!","Pas godt på dig selv!","Hav en god tur!"],"a":"Pas godt på dig selv!","r":"'Take care!' er en venlig afskedshilsen: pas godt på dig selv."}
]$$::jsonb) AS e
JOIN (VALUES
  ('o', 'ordforråd', 'recall', 'factual', 'surface_association'),
  ('h', 'hverdagsudtryk', 'comprehension', 'conceptual', 'surface_association'),
  ('g', 'grammatik', 'application', 'applied', 'overgeneralization'),
  ('l', 'læseforståelse', 'analysis', 'inferential', 'surface_association')
) AS m(k, concept, skill, dtype, mis) ON m.k = e->>'k';
